example_solution:
import gleam/string

pub fn reverse_accumulate(
  graphemes_list: List(String),
  result: String,
) -> String {
  case graphemes_list {
    [] -> result
    [token, ..rest] -> reverse_accumulate(rest, token <> result)
  }
}

pub fn reverse(value: String) -> String {
  value
  |> string.to_graphemes
  |> reverse_accumulate("")
}

test_code:
import exercism/should
import exercism/test_runner
import reverse_string

pub fn main() {
  test_runner.main()
}

pub fn an_empty_string_test() {
  reverse_string.reverse("")
  |> should.equal("")
}

pub fn a_word_test() {
  reverse_string.reverse("robot")
  |> should.equal("tobor")
}

pub fn a_capitalized_word_test() {
  reverse_string.reverse("Ramen")
  |> should.equal("nemaR")
}

pub fn a_sentence_with_punctuation_test() {
  reverse_string.reverse("I'm hungry!")
  |> should.equal("!yrgnuh m'I")
}

pub fn a_palindrome_test() {
  reverse_string.reverse("racecar")
  |> should.equal("racecar")
}

pub fn an_even_sized_word_test() {
  reverse_string.reverse("drawer")
  |> should.equal("reward")
}
